// Turns the JSON in data/ into compile-time Rust constants.
//
// The Rust core has ZERO dependencies — no serde, no JSON parsing, no file I/O
// at all. That is partly forced (the crates.io registry is not reachable from
// the build environment) and partly the right answer anyway: a crate whose
// language data is a compile-time constant cannot load the wrong file, cannot
// fail at startup, and compiles straight to WASM with nothing to bundle.
//
// The generated file is checked in. Regenerate it with `npm run rust:data`
// whenever data/ changes; a test on the TypeScript side fails if it is stale,
// so the two can never disagree about what the language is.
//
// Plain .mjs rather than .ts so it runs under bare node on any machine in this
// project's toolchain, with or without tsx.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";

const root = process.argv[2];
// Optional second root for the generated output, so the generator can read the
// data from one checkout and write the crate into another.
const outRoot = process.argv[3] ?? root;
if (!root) {
  console.error("usage: node scripts/buildRustData.mjs <repo-root> [out-root]");
  process.exit(1);
}

const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));
const phonology = read("data/phonology/phonology.json");

const str = (s) => JSON.stringify(s);
const strSlice = (arr) => `&[${arr.map(str).join(", ")}]`;

const lines = [];
const w = (s = "") => lines.push(s);

w("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
w("//");
w("// Compiled from the JSON in data/, which is the single source of truth for");
w("// the language. Edit the JSON and run `npm run rust:data`; editing this file");
w("// directly puts Rust and TypeScript into disagreement about what Gurzûl Khar");
w("// is, which is exactly what the shared fixtures exist to prevent.");
w(`// Source data version: phonology ${phonology.version}`);
w();
w("/// A consonant as declared in data/phonology/phonology.json.");
w("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
w("pub struct Consonant {");
w("    /// Phonology id, e.g. `\"kh\"`.");
w("    pub id: &'static str,");
w("    /// How it is written.");
w("    pub latin: &'static str,");
w("    /// How it is pronounced.");
w("    pub ipa: &'static str,");
w("    /// Place of articulation.");
w("    pub place: &'static str,");
w("    /// Manner of articulation.");
w("    pub manner: &'static str,");
w("    /// Voiced or voiceless.");
w("    pub voicing: &'static str,");
w("    /// Where in a word it may occur: initial, medial, final.");
w("    pub positions: &'static [&'static str],");
w("}");
w();
w("/// A vowel: short, long, or a diphthong. `written_variants` carries accepted");
w("/// alternate spellings of the SAME vowel — \"ü\" is a written variant of \"û\".");
w("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
w("pub struct Vowel {");
w("    /// Phonology id, e.g. `\"\u00fb\"`.");
w("    pub id: &'static str,");
w("    /// How it is written.");
w("    pub latin: &'static str,");
w("    /// How it is pronounced.");
w("    pub ipa: &'static str,");
w("    /// True for a long vowel. Length is meaningful: it distinguishes words.");
w("    pub is_long: bool,");
w("    /// True for a diphthong.");
w("    pub is_diphthong: bool,");
w("    /// Accepted alternate spellings of this same vowel.");
w("    pub written_variants: &'static [&'static str],");
w("}");
w();

w("/// Every consonant the language declares, in data order.");
w("pub static CONSONANTS: &[Consonant] = &[");
for (const c of phonology.consonants) {
  w(`    Consonant { id: ${str(c.id)}, latin: ${str(c.latin)}, ipa: ${str(c.ipa)}, place: ${str(c.place)}, manner: ${str(c.manner)}, voicing: ${str(c.voicing)}, positions: ${strSlice(c.positions)} },`);
}
w("];");
w();

const vowelRows = (list, isLong, isDiph) =>
  list.map(
    (v) =>
      `    Vowel { id: ${str(v.id)}, latin: ${str(v.latin)}, ipa: ${str(v.ipa)}, is_long: ${isLong}, is_diphthong: ${isDiph}, written_variants: ${strSlice(v.writtenVariants ?? [])} },`
  );

w("/// The short vowels.");
w("pub static SHORT_VOWELS: &[Vowel] = &[");
vowelRows(phonology.vowels.short, false, false).forEach(w);
w("];");
w();
w("/// The long vowels. A circumflex marks length, and length changes the word.");
w("pub static LONG_VOWELS: &[Vowel] = &[");
vowelRows(phonology.vowels.long, true, false).forEach(w);
w("];");
w();
w("/// The diphthongs, each a single atomic nucleus.");
w("pub static DIPHTHONGS: &[Vowel] = &[");
vowelRows(phonology.vowels.diphthongs, false, true).forEach(w);
w("];");
w();

w("/// Two-consonant onsets the phonotactics permit.");
w(`pub static ONSET_CLUSTERS: &[&str] = ${strSlice(phonology.phonotactics.onsetClusters.allowed)};`);
w();
w("/// Two-consonant codas the phonotactics permit.");
w(`pub static CODA_CLUSTERS: &[&str] = ${strSlice(phonology.phonotactics.codaClusters.allowed)};`);
w();
w(`/// ${phonology.stress.defaultRule}`);
w("/// The default stress rule, as documented.");
w("pub static STRESS_DEFAULT_RULE: &str = " + str(phonology.stress.defaultRule) + ";");
w();

const outPath = join(outRoot, "crates/gkh-core/src/data/generated.rs");
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, lines.join("\n") + "\n", "utf8");
console.log(`wrote ${outPath} (${phonology.consonants.length} consonants, ${phonology.vowels.short.length + phonology.vowels.long.length + phonology.vowels.diphthongs.length} vowels)`);

// --- test fixtures -------------------------------------------------------
const fixtures = read("tests/fixtures/phonotactics.json");
const fx = [];
fx.push("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
fx.push("//");
fx.push("// The SAME cases tests/phonotacticFixture.test.ts asserts on the TypeScript");
fx.push("// side. If the two engines ever disagree about one of these words, one of");
fx.push("// the two suites goes red — which is the whole point of the port.");
fx.push("");
fx.push("/// One pinned word and the violations it must produce.");
fx.push("pub struct FixtureCase {");
fx.push("    /// The word under test.");
fx.push("    pub word: &'static str,");
fx.push("    /// Whether it is fully legal.");
fx.push("    pub valid: bool,");
fx.push("    /// The violation codes it must produce, in order.");
fx.push("    pub codes: &'static [&'static str],");
fx.push("}");
fx.push("");
fx.push("/// The shared phonotactic fixtures.");
fx.push("pub static PHONOTACTIC_CASES: &[FixtureCase] = &[");
for (const c of fixtures.cases) {
  fx.push(`    FixtureCase { word: ${str(c.word)}, valid: ${c.valid}, codes: ${strSlice(c.codes)} },`);
}
fx.push("];");
const fxPath = join(outRoot, "crates/gkh-core/tests/generated/phonotactics.rs");
mkdirSync(dirname(fxPath), { recursive: true });
writeFileSync(fxPath, fx.join("\n") + "\n", "utf8");
console.log(`wrote ${fxPath} (${fixtures.cases.length} cases)`);
